  function chooser9(){return breadcrumb('راهنمای انتخاب')+`<section class="shell chooser-intro"><span class="eyebrow">GUIDED EQUIPMENT SELECTION</span><h1>نیازتان را روشن‌تر کنید.</h1><p>این راهنما خانوادهٔ مرتبط را بر اساس نوع کاربرد نشان می‌دهد؛ اطلاعات فنی شما برای بررسی کارشناس همراه درخواست قرار می‌گیرد.</p></section><section class="shell chooser-layout"><aside class="chooser-sidebar"><h2>مسیر انتخاب</h2><ol class="wizard-steps">${['نوع کاربرد','قطعه و متریال','نیاز تولید','نتیجهٔ اولیه'].map((s,i)=>`<li data-wizard-step="${i}"><span>${num(i+1)}</span><div><b>${s}</b><small>${['چه کاری انجام می‌دهید؟','با چه قطعه‌ای کار می‌کنید؟','گردش کارتان چگونه است؟','مرور گزینه‌ها و درخواست'][i]}</small></div></li>`).join('')}</ol><div class="wizard-sidebar-note">${icon('head')}<p>نام مدل به‌تنهایی کافی نیست. توان، ابعاد و پیکربندی باید با قطعه و شرایط کار تطبیق داده شوند.</p></div></aside><div class="wizard-main"><div class="wizard-progress" role="progressbar" aria-label="پیشرفت راهنمای انتخاب" aria-valuemin="1" aria-valuemax="4" aria-valuenow="1"><span></span></div><div id="wizard-screen"></div></div></section>`;}
  function wizardSummary9(){const u=getUse9();return [u?'کاربرد: '+u.name:'',wizard9.use==='parts'?'خانوادهٔ قطعه: '+label(wizard9.part):'متریال: '+formLabel9(materials9,wizard9.material),wizard9.thickness?'ضخامت اعلامی: '+wizard9.thickness+' میلی‌متر':'',wizard9.width?'عرض اعلامی: '+wizard9.width+' میلی‌متر':'',wizard9.length?'طول اعلامی: '+wizard9.length+' میلی‌متر':'',wizard9.model?'مدل دستگاه موجود: '+wizard9.model:'','حجم کار: '+formLabel9(volumes9,wizard9.volume),wizard9.format?'توضیح گردش کار: '+wizard9.format:'',wizard9.note?'توضیحات: '+wizard9.note:''].filter(Boolean);}
